def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def is_err(v: object) -> bool:
        return isinstance(v, str)

    def tdiv(a: int, b: int) -> int | str:
        if b == 0:
            return "#DIV/0!"
        sign = -1 if (a < 0) != (b < 0) else 1
        return sign * (abs(a) // abs(b))

    def cmp_op(op: str, a: int, b: int) -> bool:
        if op == "=":
            return a == b
        if op == "<>":
            return a != b
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b

    def eval_node(node):
        k = node[0]
        if k == "num":
            return node[1]
        if k == "cell":
            return eval_cell(node[1])
        if k == "neg":
            v = eval_node(node[1])
            return v if is_err(v) else -v
        if k == "bin":
            op, left, right = node[1], node[2], node[3]
            lv = eval_node(left)
            if is_err(lv):
                return lv
            rv = eval_node(right)
            if is_err(rv):
                return rv
            if op == "+":
                return lv + rv
            if op == "-":
                return lv - rv
            if op == "*":
                return lv * rv
            return tdiv(lv, rv)
        if k == "agg":
            vals: list[int] = []
            for arg in node[2]:
                if arg[0] == "range":
                    c1, r1, c2, r2 = arg[1], arg[2], arg[3], arg[4]
                    for rr in range(min(r1, r2), max(r1, r2) + 1):
                        lo = min(ord(c1), ord(c2))
                        hi = max(ord(c1), ord(c2))
                        for cc in range(lo, hi + 1):
                            name = chr(cc) + str(rr)
                            if name not in cells:
                                continue
                            v = eval_cell(name)
                            if is_err(v):
                                return v
                            vals.append(v)
                else:
                    v = eval_node(arg)
                    if is_err(v):
                        return v
                    vals.append(v)
            fn = node[1]
            if fn == "MIN" and vals:
                return min(vals)
            if fn == "MAX" and vals:
                return max(vals)
            return sum(vals)
        left, op, right, then_b, else_b = node[1], node[2], node[3], node[4], node[5]
        lv = eval_node(left)
        if is_err(lv):
            return lv
        rv = eval_node(right)
        if is_err(rv):
            return rv
        return eval_node(then_b if cmp_op(op, lv, rv) else else_b)

    def eval_cell(name: str):
        if name not in cells:
            return 0
        if name in memo:
            return memo[name]
        if name in visiting:
            return "#CYCLE!"
        visiting.add(name)
        raw = cells[name].strip()
        if raw.startswith("="):
            val = eval_node(parse(raw[1:]))
        else:
            val = int(raw)
        visiting.remove(name)
        memo[name] = val
        return val

    def parse(s: str):
        i = 0
        n = len(s)

        def skip() -> None:
            nonlocal i
            while i < n and s[i] == " ":
                i += 1

        def read_digits() -> str:
            nonlocal i
            j = i
            while i < n and s[i].isdigit():
                i += 1
            return s[j:i]

        def parse_expr():
            nonlocal i
            left = parse_term()
            while True:
                skip()
                if i < n and s[i] in "+-":
                    op = s[i]
                    i += 1
                    right = parse_term()
                    left = ("bin", op, left, right)
                else:
                    break
            return left

        def parse_term():
            nonlocal i
            left = parse_unary()
            while True:
                skip()
                if i < n and s[i] in "*/":
                    op = s[i]
                    i += 1
                    right = parse_unary()
                    left = ("bin", op, left, right)
                else:
                    break
            return left

        def parse_unary():
            nonlocal i
            skip()
            if i < n and s[i] == "-":
                i += 1
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom():
            nonlocal i
            skip()
            ch = s[i]
            if ch.isdigit():
                return ("num", int(read_digits()))
            if ch == "(":
                i += 1
                e = parse_expr()
                skip()
                i += 1
                return e
            j = i
            while i < n and s[i].isalpha():
                i += 1
            word = s[j:i]
            if len(word) == 1 and i < n and s[i].isdigit():
                return ("cell", word + read_digits())
            skip()
            i += 1
            if word == "IF":
                left = parse_expr()
                skip()
                if s.startswith("<>", i) or s.startswith("<=", i) or s.startswith(">=", i):
                    op = s[i:i + 2]
                    i += 2
                else:
                    op = s[i]
                    i += 1
                right = parse_expr()
                skip()
                i += 1
                then_b = parse_expr()
                skip()
                i += 1
                else_b = parse_expr()
                skip()
                i += 1
                return ("if", left, op, right, then_b, else_b)
            args = [parse_arg()]
            while True:
                skip()
                if s[i] == ",":
                    i += 1
                    args.append(parse_arg())
                else:
                    break
            skip()
            i += 1
            return ("agg", word, args)

        def starts_range() -> bool:
            j = i
            while j < n and s[j] == " ":
                j += 1
            if j >= n or not s[j].isalpha():
                return False
            if j + 1 < n and s[j + 1].isalpha():
                return False
            j += 1
            if j >= n or not s[j].isdigit():
                return False
            while j < n and s[j].isdigit():
                j += 1
            while j < n and s[j] == " ":
                j += 1
            return j < n and s[j] == ":"

        def parse_cell_ends():
            nonlocal i
            skip()
            col = s[i]
            i += 1
            row = int(read_digits())
            return col, row

        def parse_arg():
            nonlocal i
            if starts_range():
                c1, r1 = parse_cell_ends()
                skip()
                i += 1
                c2, r2 = parse_cell_ends()
                return ("range", c1, r1, c2, r2)
            return parse_expr()

        return parse_expr()

    return {name: eval_cell(name) for name in cells}
